(()=>{'use strict';
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
function closeMenu(){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();toggle.focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu()});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
const form=document.querySelector('#quote-form');if(!form)return;
const panels=[...form.querySelectorAll('.form-step')],markers=[...form.querySelectorAll('.form-progress span')];let step=0;
const labels={service:'Leistung',postal:'Postleitzahl',city:'Ort',date:'Wunschtermin',details:'Projektbeschreibung',name:'Name',email:'E-Mail',phone:'Telefon'};
const aliases={'water-tank-cleaning':'dachbeschichtung-versiegelung','commercial-cleaning':'dachreinigung-entmoosung','packers-and-movers':'fassadenreinigung-beschichtung','waste-and-scrap-pickup':'dachinspektion-reparatur'};const raw=new URLSearchParams(location.search).get('service');const param=aliases[raw]||raw;if([...form.service.options].some(o=>o.value===param))form.service.value=param;
const now=new Date();form.date.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
function values(){const data=Object.fromEntries(new FormData(form));data.service=form.service.selectedOptions[0].text;if(data.date){const [year,month,day]=data.date.split('-');data.date=day+'.'+month+'.'+year}return data}
function review(){const box=document.querySelector('#quote-review');box.replaceChildren();const data=values();for(const [key,label]of Object.entries(labels)){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=data[key]||'Nicht angegeben';box.append(dt,dd)}}
function show(next){step=next;panels.forEach((el,i)=>el.hidden=i!==next);markers.forEach((el,i)=>el.classList.toggle('active',i===next));if(next===2)review();const h=panels[next].querySelector('h2');h.tabIndex=-1;h.focus({preventScroll:true});form.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function validateField(field){field.setCustomValidity('');if(field.validity.valueMissing)field.setCustomValidity(field.type==='checkbox'?'Bitte bestätigen Sie die Angaben.':'Bitte füllen Sie dieses Pflichtfeld aus.');else if(field.validity.typeMismatch)field.setCustomValidity('Bitte geben Sie eine gültige E-Mail-Adresse ein.');else if(field.validity.patternMismatch)field.setCustomValidity('Bitte geben Sie eine fünfstellige deutsche Postleitzahl ein.');else if(field.id==='details'&&field.value.trim().length<15)field.setCustomValidity('Bitte beschreiben Sie Ihr Vorhaben mit mindestens 15 Zeichen.');else if(field.validity.rangeUnderflow)field.setCustomValidity('Bitte wählen Sie heute oder ein zukünftiges Datum.');return field.checkValidity()}
form.querySelectorAll('input,select,textarea').forEach(f=>{f.addEventListener('input',()=>f.setCustomValidity(''));f.addEventListener('change',()=>f.setCustomValidity(''))});
function validPanel(index){for(const field of panels[index].querySelectorAll('input,textarea,select')){if(!validateField(field)){field.reportValidity();return false}}return true}
form.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>{if(validPanel(step))show(step+1)}));form.querySelectorAll('[data-back]').forEach(b=>b.addEventListener('click',()=>show(step-1)));
form.noValidate=true;
form.addEventListener('submit',event=>{event.preventDefault();if(step<2){if(validPanel(step))show(step+1);return}for(let i=0;i<2;i++){for(const f of panels[i].querySelectorAll('input,textarea,select'))if(!validateField(f)){show(i);f.reportValidity();return}}
const data=values();const text='BARTSCH & LOßNER GMBH — ANFRAGE\n\n'+Object.entries(labels).map(([k,l])=>l+': '+(data[k]||'Nicht angegeben')).join('\n\n')+'\n\nAnfrage an Bartsch & Loßner GmbH (Pestalozzistraße 25, 22305 Hamburg-Nord, Tel: +49 40 64413366).\n';const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='bartsch-lossner-anfrage.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Ihre Anfrage wurde zusammengestellt. Der Download wurde gestartet.'});
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'stage_service_brief',description:'Füllt die sichtbaren Projektfelder zur Prüfung aus.',inputSchema:{type:'object',properties:{service:{type:'string',enum:[...form.service.options].map(o=>o.value).filter(Boolean)},city:{type:'string'},details:{type:'string'}},required:['service'],additionalProperties:false},execute:async input=>{if(!input||typeof input.service!=='string'||![...form.service.options].some(o=>o.value===input.service&&o.value))throw new Error('Bitte eine verfügbare Leistung auswählen');for(const key of ['city','details'])if(input[key]!==undefined&&(typeof input[key]!=='string'||input[key].length>(key==='city'?100:2500)))throw new Error('Ungültige Angabe: '+key);form.service.value=input.service;for(const key of ['city','details'])if(input[key]!==undefined)form.elements[key].value=input[key];show(0);return{content:[{type:'text',text:'Die Projektfelder sind ausgefüllt.'}]}}});addEventListener('pagehide',()=>navigator.modelContext?.unregisterTool?.('stage_service_brief'),{once:true})}catch{ /* Ordinary form remains available in unsupported implementations. */ }}
})();
